{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace table suroskie-wh-455109.maplemonk.Suroskie_Abandoned_Checkout_Fact_items as WITH CheckOut_Order_level AS ( SELECT DISTINCT c.id AS checkout_id, CAST(c.created_at AS DATETIME) AS created_at, JSON_VALUE(c.customer, \'$.id\') AS checkout_customer_id, REPLACE( COALESCE( JSON_VALUE(c.customer, \'$.first_name\'), JSON_VALUE(c.billing_address, \'$.first_name\'), JSON_VALUE(c.shipping_address, \'$.first_name\') ), \'\"\', \'\' ) AS first_name, REPLACE( COALESCE( JSON_VALUE(c.customer, \'$.last_name\'), JSON_VALUE(c.billing_address, \'$.last_name\'), JSON_VALUE(c.shipping_address, \'$.last_name\') ), \'\"\', \'\' ) AS last_name, COALESCE( c.email, JSON_VALUE(c.billing_address, \'$.email\'), JSON_VALUE(c.shipping_address, \'$.email\'), JSON_VALUE(c.customer, \'$.email\') ) AS email, COALESCE( JSON_VALUE(c.billing_address, \'$.phone\'), JSON_VALUE(c.shipping_address, \'$.phone\'), JSON_VALUE(c.customer, \'$.phone\') ) AS phone_number, CASE WHEN CAST(JSON_VALUE(c.customer, \'$.orders_count\') AS INT64) = 0 THEN \'New\' ELSE \'Repeat\' END AS New_Customer_Flag FROM suroskie-wh-455109.maplemonk.shopify_suroskie_abandoned_checkouts c WHERE IFNULL(DATETIME_DIFF(CAST(c.completed_at AS DATETIME), CAST(c.created_at AS DATETIME), HOUR), 0) >= 6 OR c.completed_at IS NULL ), Sales_Order_Level AS ( SELECT DISTINCT CAST(s.created_at AS DATETIME) AS sales_order_date, JSON_VALUE(s.customer, \'$.id\') AS sales_customer_id, s.name AS reference_code FROM suroskie-wh-455109.maplemonk.shopify_suroskie_orders s ), order_level_checkout_Sales_Data_duplicates_reference_Code AS ( SELECT col.*, sol.sales_order_date, sol.reference_code FROM CheckOut_Order_level col LEFT JOIN Sales_Order_Level sol ON col.checkout_customer_id = sol.sales_customer_id AND sol.sales_order_date BETWEEN col.created_at AND DATETIME_ADD(col.created_at, INTERVAL 10 DAY) WHERE sol.reference_code IS NOT NULL ), order_level_checkout_Sales_Data AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY checkout_id ORDER BY sales_order_date ASC) AS c_rw, ROW_NUMBER() OVER (PARTITION BY reference_code ORDER BY created_at DESC) AS rw FROM order_level_checkout_Sales_Data_duplicates_reference_Code ) WHERE c_rw = 1 AND rw = 1 ), checkout_data AS ( SELECT DISTINCT c.id AS checkout_id, CAST(c.created_at AS DATETIME) AS created_at, REPLACE(JSON_VALUE(item, \'$.sku\'), \'\"\', \'\') AS checkout_sku, CAST(REPLACE(JSON_VALUE(item, \'$.price\'), \'\"\', \'\') AS FLOAT64) AS checkout_price, JSON_VALUE(c.customer, \'$.id\') AS checkout_customer_id, REPLACE( COALESCE( JSON_VALUE(c.customer, \'$.first_name\'), JSON_VALUE(c.billing_address, \'$.first_name\'), JSON_VALUE(c.shipping_address, \'$.first_name\') ), \'\"\', \'\' ) AS first_name, REPLACE( COALESCE( JSON_VALUE(c.customer, \'$.last_name\'), JSON_VALUE(c.billing_address, \'$.last_name\'), JSON_VALUE(c.shipping_address, \'$.last_name\') ), \'\"\', \'\' ) AS last_name, c.buyer_accepts_marketing, COALESCE( c.email, JSON_VALUE(c.billing_address, \'$.email\'), JSON_VALUE(c.shipping_address, \'$.email\'), JSON_VALUE(c.customer, \'$.email\') ) AS email, COALESCE( JSON_VALUE(c.billing_address, \'$.phone\'), JSON_VALUE(c.shipping_address, \'$.phone\'), JSON_VALUE(c.customer, \'$.phone\') ) AS phone_number, CASE WHEN CAST(JSON_VALUE(c.customer, \'$.orders_count\') AS INT64) = 0 THEN \'New\' ELSE \'Repeat\' END AS New_Customer_Flag FROM suroskie-wh-455109.maplemonk.shopify_suroskie_abandoned_checkouts c, UNNEST(c.line_items) AS item WHERE IFNULL(DATETIME_DIFF(CAST(c.completed_at AS DATETIME), CAST(c.created_at AS DATETIME), HOUR), 0) >= 6 OR c.completed_at IS NULL ), shopify_data AS ( SELECT CAST(s.created_at AS DATETIME) AS sales_order_date, JSON_VALUE(s.customer, \'$.id\') AS sales_customer_id, s.name AS reference_code, REPLACE(JSON_VALUE(item, \'$.sku\'), \'\"\', \'\') AS sales_sku, SUM(CAST(REPLACE(JSON_VALUE(item, \'$.price\'), \'\"\', \'\') AS FLOAT64)) AS order_price FROM suroskie-wh-455109.maplemonk.shopify_suroskie_orders s, UNNEST(s.line_items) AS item GROUP BY 1,2,3,4 ), checkout_fact_items AS ( SELECT c.*, s.reference_code, s.sales_order_date, s.sales_sku, s.order_price FROM checkout_data c FULL OUTER JOIN shopify_data s ON c.checkout_customer_id = s.sales_customer_id AND c.checkout_sku = s.sales_sku AND s.sales_order_date BETWEEN c.created_at AND DATETIME_ADD(c.created_at, INTERVAL 10 DAY) ), final_checkout_fact_items AS ( SELECT COALESCE(c.created_at, ocd.created_at) AS date, COALESCE(c.checkout_customer_id, ocd.checkout_customer_id) AS customer_id, COALESCE(c.checkout_id, ocd.checkout_id) AS checkout_id, COALESCE(c.New_Customer_Flag, ocd.New_Customer_Flag) AS New_Customer_Flag, COALESCE(c.last_name, ocd.last_name) AS last_name, COALESCE(c.first_name, ocd.first_name) AS first_name, COALESCE(c.phone_number, ocd.phone_number) AS phone_number, COALESCE(c.email, ocd.email) AS email, DATETIME_DIFF(COALESCE(c.sales_order_date, ocd.sales_order_date), COALESCE(c.created_at, ocd.created_at), HOUR) AS conversion_time, c.checkout_sku, c.checkout_price, c.reference_code, c.sales_sku, c.order_price FROM checkout_fact_items c LEFT JOIN order_level_checkout_Sales_Data ocd ON c.reference_code = ocd.reference_code ), percentile AS ( SELECT date, MAX(percentile_90) AS percentile_90, MAX(percentile_50) AS percentile_50 FROM ( SELECT date, PERCENTILE_DISC(conversion_time, 0.9) OVER (PARTITION BY date) AS percentile_90, PERCENTILE_DISC(conversion_time, 0.5) OVER (PARTITION BY date) AS percentile_50 FROM ( SELECT DISTINCT date, reference_code, conversion_time FROM final_checkout_fact_items WHERE checkout_id IS NOT NULL AND reference_code IS NOT NULL ) ) GROUP BY date ), average AS ( SELECT date, AVG(IFNULL(conversion_time, 0)) AS AVG_conversion_time FROM ( SELECT DISTINCT date, reference_code, conversion_time FROM final_checkout_fact_items WHERE checkout_id IS NOT NULL AND reference_code IS NOT NULL ) GROUP BY date ), Conversion_type AS ( SELECT reference_code, CASE WHEN COUNT(*) = SUM(sku_present_flag) THEN \'Good Convert\' WHEN SUM(sku_present_flag) = 0 THEN \'Different Convert\' ELSE \'Partial Convert\' END AS order_conversion_type FROM ( SELECT DISTINCT c.checkout_id, r.reference_code, r.sales_sku, CASE WHEN LOWER(total_skus) LIKE CONCAT(\'%\', LOWER(r.sales_sku), \'%\') THEN 1 ELSE 0 END AS sku_present_flag FROM ( SELECT checkout_id, STRING_AGG(checkout_sku, \', \' ORDER BY checkout_sku) AS total_skus FROM checkout_data WHERE checkout_id IS NOT NULL GROUP BY checkout_id ) c LEFT JOIN ( SELECT DISTINCT checkout_id, reference_code, IFNULL(sales_sku, \'no_sku\') AS sales_sku FROM final_checkout_fact_items WHERE reference_code IS NOT NULL AND checkout_id IS NOT NULL ) r ON c.checkout_id = r.checkout_id ) GROUP BY reference_code ) SELECT cfi.*, ct.order_conversion_type, p.percentile_50, p.percentile_90, a.AVG_conversion_time, CASE WHEN cfi.checkout_id IS NOT NULL AND cfi.reference_code IS NOT NULL THEN \'Converted\' ELSE \'Not Converted\' END AS Checkout_Status, DATE_DIFF(CURRENT_DATE(), DATE(cfi.date), DAY) AS days_since_checkout_created FROM final_checkout_fact_items cfi LEFT JOIN Conversion_type ct ON ct.reference_code = cfi.reference_code LEFT JOIN percentile p ON cfi.date = p.date LEFT JOIN average a ON cfi.date = a.date WHERE cfi.checkout_id IS NOT NULL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            